// 位于 arch/x86/mm/numa.c
struct pglist_data *node_data[MAX_NUMNODES] __read_mostly;
EXPORT_SYMBOL(node_data);
// 返回系统全局扁平的、通过 Node ID 直接索引的指针数组 node_data[node_id]
// 每个数组元素代表每个 Node 的地址指针

// 位于 include/linux/mmzone.h
struct zone { // 定义 Zone 结构体
...
unsigned long watermark[NR_WMARK]; // 定义内存回收的阈值
unsigned long zone_start_pfn; // 当前 Zone 的起始物理页帧号（DMA或DMA32或Normal）
unsigned long spanned_pages; // 当前 Zone 跨越的总物理页数（含空洞）
unsigned long present_pages; // 当前 Zone 实际存在的物理页数
struct free_area free_area[MAX_ORDER];
// 伙伴系统空闲链表数组（MAX_ORDER 11）
// 用于 Buddy Allocator（伙伴分配器），管理不同阶数（order）的空闲页块链表
enum pgdat_flags { // 物理页面状态标记
PGDAT_CONGESTED,
PGDAT_DIRTY,
PGDAT_WRITEBACK,
PGDAT_RECLAIM_LOCKED,
}
...
};

// 位于 include/linux/mm_types.h
struct page {
...
union {
struct {
struct list_head lru;
...
};
...
};
};

// 位于 include/linux/mmzone.h
struct lruvec {
...
struct list_head lists[NR_LRU_LISTS];
// 通过该枚举值索引到具体的 list_head 双向链表，
// 实现按页类型的分类管理和回收优先级控制。
...
};

// 位于 include/linux/mmzone.h
enum lru_list {
LRU_INACTIVE_ANON = LRU_BASE, // 索引 0
LRU_ACTIVE_ANON = LRU_BASE + LRU_ACTIVE, // 索引 1
LRU_INACTIVE_FILE = LRU_BASE + LRU_FILE, // 索引 2
LRU_ACTIVE_FILE = LRU_BASE + LRU_FILE + LRU_ACTIVE, // 索引 3
LRU_UNEVICTABLE, // 索引 4
NR_LRU_LISTS
};

// 位于 arch/x86/mm/numa.c
enum zone_type {
// 定义 ZONE 类型分类
...
ZONE_DMA, // 索引 0
ZONE_DMA32, // 索引 1
ZONE_NORMAL, // 索引 2
__MAX_NR_ZONES
...
};

// 位于 include/linux/mmzone.h
struct free_area {
struct list_head free_list[MIGRATE_TYPES];
// 按多个迁移类型的空闲页块管理的双向链表头节点（enum migratetype）
unsigned long nr_free;
// 该 order 的总空闲页面数
};
// free_area[0]~free_area[10] 共11个 free_area
// 伙伴系统为每个 free_area 分配空闲物理页面

// 位于 arch/x86/include/asm/page.h
#define __va(x) ((void *)((unsigned long)(x)+PAGE_OFFSET))
// 说明：
// __va：宏名，virtual address 的缩写
// x：输入参数，物理地址
// (unsigned long)(x)：将物理地址转为无符号长整数类型，确保可算数运算。
// +PAGE_OFFSET：加上内核虚拟地址起始偏移
// (void *)：将结果转为指针类型
// 相当于：内核虚拟地址 = 物理地址 + PAGE_OFFSET

// 位于 arch/x86/include/asm/pgtable_64_types.h
// 定义每个页表的目录项与页表项的数目
#define PTRS_PER_PGD 512
#define MAX_PTRS_PER_P4D 512
#define PTRS_PER_P4D ptrs_per_p4d #define PTRS_PER_PUD 512
#define PTRS_PER_PMD 512
#define PTRS_PER_PTE 512
// 说明：
// PGD、P4D、PUD、PMD、PTE 等各级页表各占1个 4KiB page，
// PGD、P4D、PUD、PMD 的每个目录项占 8 个字节，共 512 项。
// PTE 的每个页表项占 8 个字节，共 512 项。

1. 编辑以下 C 代码文件
// pagefault_demo.c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/mman.h>
#define GB (1024ULL * 1024 * 1024)
#define PAGE_SIZE 4096
int main() {
printf("PID: %d\n", getpid());
// 分配 1GB 虚拟内存（仅分配 VMA，不分配物理页）
char *p = mmap(NULL, 1 * GB, PROT_READ | PROT_WRITE,
MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
if (p == MAP_FAILED) {
perror("mmap");
return 1;
}
printf("mmap 1GB done, addr=%p\n", (void*)p);
getchar(); // 暂停，方便 attach perf
// 逐页写入，触发缺页中断：
// 每次写入访问未映射的页 → #PF → 分配页表页 → 分配数据页 → 建立映射
printf("Touching each page...\n");
for (size_t i = 0; i < 1 * GB; i += PAGE_SIZE) {
p[i] = 'A'; // 写时触发 do_page_fault
}
printf("Done. Press enter to exit.\n");
getchar();
munmap(p, 1 * GB);
return 0;
}
2. 编译示例程序
$ gcc -O0 -g -o pagefault_demo pagefault_demo.c
3. 第一个终端执行
$ ./pagefault_demo
PID: 39277
mmap 1GB done, addr=0x7f50c5e63000 #此进程在前台继续执行
4. 第二个终端执行，获取内核函数调用栈。
$ sudo perf record \
-a -g --call-graph=dwarf -p $(pidof pagefault_demo)
5. 第三个终端执行，追踪进程调用的指定内核函数
以下三个函数是页表页分配和数据页分配的核心函数
$ sudo bpftrace -e '
kprobe:handle_mm_fault {
printf("handle_mm_fault called by %s (pid %d)\n", comm, pid);
}
kprobe:do_anonymous_page {
printf("do_anonymous_page called by %s (pid %d)\n", comm, pid);
}
kprobe:__alloc_pages_nodemask {
printf("__alloc_pages_nodemask called by %s (pid %d)\n", comm, pid);
}' > pagefault_tracing.log
6. 返回第一个终端输入若干字符返回触发缺页异常，在第二个终端 Ctrl+C 中断执行。
7. 在第三个终端 Ctrl+C 中断执行
8. 执行以下命令获取内核函数调用栈
$ sudo perf report -i ./perf.data
9. 查看 bpftrace 追踪日志查看是否触发调用
$ grep pagefault_demo pagefault.log | sort -n | uniq
__alloc_pages_nodemask called by pagefault_demo (pid 39277)
do_anonymous_page called by pagefault_demo (pid 39277)
handle_mm_fault called by pagefault_demo (pid 39277)
